// Turn the AI's plain-text brief into a simple HTML email.
const pack = $('Pack emails and meetings').first().json;
const text = ($json.text || $json.output || '').trim();
if (!text) {
  // Stop here so an empty brief is never emailed. Usually the model ran out of tokens: raise Max Tokens in the model node.
  throw new Error('The AI returned an empty brief. Raise the maximum tokens in the model node and run again.');
}
// The brief never carries a working link: remove any the AI wrote, and break the dots in any
// domain name left (example[.]com) so mail apps don't turn it into a link. Email addresses stay.
const safe = text
  .replace(/\b(?:https?:\/\/|www\.)\S+/gi, '[link removed]')
  .replace(/\b(?:mailto|ftp|data|javascript|file|sms|tel):\S+/gi, '[link removed]')
  .replace(/(?<![@\w.\-])((?:[a-z0-9-]+\.)+[a-z]{2,})(?![\w@-])/gi, d => d.replace(/\./g, '[.]'));
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
let html = pack.emails_truncated
  ? '<p style="margin:6px 0"><strong>More emails arrived than this brief can show. Check your inbox for older ones.</strong></p>'
  : '';
let inList = false;
for (const raw of safe.split('\n')) {
  const line = raw.trimEnd();
  if (line.startsWith('- ')) {
    if (!inList) { html += '<ul>'; inList = true; }
    html += `<li>${inline(line.slice(2))}</li>`;
    continue;
  }
  if (inList) { html += '</ul>'; inList = false; }
  if (line.startsWith('## ')) html += `<h3 style="margin:20px 0 6px">${inline(line.slice(3))}</h3>`;
  else if (line.trim()) html += `<p style="margin:6px 0">${inline(line)}</p>`;
}
if (inList) html += '</ul>';
return [{ json: {
  to: pack.email,
  subject: `Your morning brief · ${pack.date}`,
  html: `<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.5;color:#1d1d24;max-width:640px">${html}</div>`,
} }];

// Check the settings, then work out how far back to read email.
// Reads from the end of the last brief that was sent (saved below by "Remember this brief"),
// so a missed day or a custom schedule never leaves a gap. With no saved time (first run, or a
// manual test run, which n8n doesn't save) it reads 3 days on a Monday and 1 day otherwise.
// It never reads more than 7 days back.
const s = $json;
const to = String(s.your_email || '').trim();
if (!/^[^\s@<>()",;:]+@[^\s@<>()",;:]+\.[a-z]{2,}$/i.test(to) || /@example\.(com|org|net)$/i.test(to)) {
  throw new Error('Put your own email address in "Your settings" first. The brief contains your private email, so it is never sent to a placeholder or a malformed address.');
}
const DAY = 86400000;
const nowMs = $now.toMillis();
const saved = Number($getWorkflowStaticData('global').lastBriefEndMs) || 0;
const fallbackMs = nowMs - ($now.weekday === 1 ? 3 : 1) * DAY;
let fromMs = saved > 0 && saved < nowMs ? saved : fallbackMs;
fromMs = Math.max(fromMs, nowMs - 7 * DAY);
return [{ json: { ...s, your_email: to, after_epoch: Math.floor(fromMs / 1000), window_end_ms: nowMs } }];

// The brief went out, so the next run reads from where this one stopped.
// n8n only keeps this for scheduled (active) runs; manual test runs don't change it.
$getWorkflowStaticData('global').lastBriefEndMs = $('Work out the window').first().json.window_end_ms;
return $input.all();
